// This is archive metadata only. Live requests are generated by the logged-in
// browser, never replayed with a manually assembled Cookie/UA fingerprint.
export function requestContext(request){
 const headers=request.headers();
 const result={method:request.method(),headerNames:Object.keys(headers),headers:{}};
 for(const key of ['content-type','accept','user-agent','sec-ch-ua','sec-ch-ua-mobile','sec-ch-ua-platform','x-front-version']){
  if(headers[key])result.headers[key]=headers[key];
 }
 for(const key of ['origin','referer']){
  if(headers[key]){try{const u=new URL(headers[key]);result.headers[key]=u.origin+(key==='referer'?u.pathname:'')}catch{}}
 }
 return result;
}
